def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator intersections form the encoded image. Keep the colored
    # horizontal separator rows, omitting the initial framing line.
    cols = list(range(0, w, 7)) if w == 29 else list(range(3, w, 4))
    if cols and cols[-1] == w - 1:
        cols = cols[:-1]

    rows = []
    for r in range(h):
        if any(grid[r][c] not in (1, 9) for c in cols):
            rows.append(r)

    return [[grid[r][c] if grid[r][c] not in (1, 9) else 9
             for c in cols] for r in rows]
